438:     private static boolean isPreviousRegistrationPrefixOfNewRegistration(
439:             Set<Class<?>> previousRegistrationOrder, Set<Class<?>> newRegistrationOrder) {
440:         Iterator<Class<?>> newRegistrationItr = newRegistrationOrder.iterator();
441: 
442:         for (Class<?> previousRegisteredClass : previousRegistrationOrder) {
443:             if (!newRegistrationItr.hasNext()) {
444:                 return false;
445:             }
446:             Class<?> newRegisteredClass = newRegistrationItr.next();
447:             if (!previousRegisteredClass.equals(newRegisteredClass)) {
448:                 return false;
449:             }
450:         }
451:         return true;
452:     }
