276:     /**
277:      * Transforms the subclass serializer registry structure, {@code LinkedHashMap<Class<?>,
278:      * TypeSerializer<?>>} to 2 separate structures: a map containing with registered classes as key
279:      * and their corresponding ids (order in the original map) as value, as well as a separate array
280:      * of the corresponding subclass serializers.
281:      */
282:     @SuppressWarnings("unchecked")
283:     private static Tuple2<LinkedHashMap<Class<?>, Integer>, TypeSerializer<Object>[]>
284:             decomposeSubclassSerializerRegistry(
285:                     LinkedHashMap<Class<?>, TypeSerializer<?>> subclassSerializerRegistry) {
286: 
287:         final LinkedHashMap<Class<?>, Integer> subclassIds =
288:                 CollectionUtil.newLinkedHashMapWithExpectedSize(subclassSerializerRegistry.size());
289:         final TypeSerializer[] subclassSerializers =
290:                 new TypeSerializer[subclassSerializerRegistry.size()];
291: 
292:         subclassSerializerRegistry.forEach(
293:                 (registeredSubclassClass, serializer) -> {
294:                     int id = subclassIds.size();
295:                     subclassIds.put(registeredSubclassClass, id);
296:                     subclassSerializers[id] = serializer;
297:                 });
298: 
299:         return Tuple2.of(subclassIds, subclassSerializers);
300:     }
