302:     /**
303:      * Finds which Pojo fields exists both in the new {@link PojoSerializerSnapshot} as well as in
304:      * the previous one, and returns an {@link IntermediateCompatibilityResult} of the serializers
305:      * of those preexisting fields.
306:      */
307:     private IntermediateCompatibilityResult<T> getCompatibilityOfPreExistingFields(
308:             LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> oldFieldSerializerSnapshots) {
309: 
310:         // the present entries dictates the preexisting fields, because removed fields would be
311:         // represented as absent keys in the optional map.
312:         final Set<LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>>>
313:                 presentFieldSnapshots = oldFieldSerializerSnapshots.getPresentEntries();
314: 
315:         final ArrayList<TypeSerializerSnapshot<?>> associatedFieldSerializerSnapshots =
316:                 new ArrayList<>(presentFieldSnapshots.size());
317:         final ArrayList<TypeSerializerSnapshot<?>> associatedNewFieldSerializerSnapshots =
318:                 new ArrayList<>(presentFieldSnapshots.size());
319: 
320:         Map<Field, TypeSerializerSnapshot<?>> newFieldSerializerSnapshots =
321:                 snapshotData.getFieldSerializerSnapshots().unwrapOptionals();
322:         for (LinkedOptionalMap.KeyValue<Field, TypeSerializerSnapshot<?>> presentFieldEntry :
323:                 presentFieldSnapshots) {
324:             TypeSerializerSnapshot<?> associatedNewFieldSerializer =
325:                     newFieldSerializerSnapshots.get(presentFieldEntry.getKey());
326:             checkState(
327:                     associatedNewFieldSerializer != null,
328:                     "a present field should have its associated new field serializer available.");
329: 
330:             associatedFieldSerializerSnapshots.add(presentFieldEntry.getValue());
331:             associatedNewFieldSerializerSnapshots.add(associatedNewFieldSerializer);
332:         }
333: 
334:         return CompositeTypeSerializerUtil.constructIntermediateCompatibilityResult(
335:                 associatedNewFieldSerializerSnapshots.toArray(
336:                         new TypeSerializerSnapshot<?>
337:                                 [associatedNewFieldSerializerSnapshots.size()]),
338:                 associatedFieldSerializerSnapshots.toArray(
339:                         new TypeSerializerSnapshot<?>[associatedFieldSerializerSnapshots.size()]));
340:     }
