342:     /**
343:      * Finds which registered subclasses exists both in the new {@link PojoSerializerSnapshot} as
344:      * well as in the previous one, and returns an {@link IntermediateCompatibilityResult} of the
345:      * serializers of this preexisting registered subclasses.
346:      */
347:     private IntermediateCompatibilityResult<T> getCompatibilityOfPreExistingRegisteredSubclasses(
348:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
349:                     registeredSubclassSerializerSnapshots) {
350: 
351:         final LinkedHashMap<Class<?>, TypeSerializerSnapshot<?>> unwrappedSerializerSnapshots =
352:                 registeredSubclassSerializerSnapshots.unwrapOptionals();
353: 
354:         final ArrayList<TypeSerializerSnapshot<?>> associatedSubclassSerializerSnapshots =
355:                 new ArrayList<>();
356:         final ArrayList<TypeSerializerSnapshot<?>> associatedNewSubclassSerializerSnapshots =
357:                 new ArrayList<>();
358: 
359:         final LinkedHashMap<Class<?>, TypeSerializerSnapshot<?>> newSubclassSerializerRegistry =
360:                 snapshotData.getRegisteredSubclassSerializerSnapshots().unwrapOptionals();
361: 
362:         for (Map.Entry<Class<?>, TypeSerializerSnapshot<?>> entry :
363:                 unwrappedSerializerSnapshots.entrySet()) {
364:             TypeSerializerSnapshot<?> newRegisteredSerializerSnapshot =
365:                     newSubclassSerializerRegistry.get(entry.getKey());
366:             if (newRegisteredSerializerSnapshot != null) {
367:                 associatedSubclassSerializerSnapshots.add(entry.getValue());
368:                 associatedNewSubclassSerializerSnapshots.add(newRegisteredSerializerSnapshot);
369:             }
370:         }
371: 
372:         return CompositeTypeSerializerUtil.constructIntermediateCompatibilityResult(
373:                 associatedNewSubclassSerializerSnapshots.toArray(
374:                         new TypeSerializerSnapshot<?>
375:                                 [associatedNewSubclassSerializerSnapshots.size()]),
376:                 associatedSubclassSerializerSnapshots.toArray(
377:                         new TypeSerializerSnapshot<?>
378:                                 [associatedSubclassSerializerSnapshots.size()]));
379:     }
