381:     /** Checks if the new {@link PojoSerializerSnapshot} is compatible after migration. */
382:     private boolean newPojoSerializerIsCompatibleAfterMigration(
383:             IntermediateCompatibilityResult<T> fieldSerializerCompatibility,
384:             IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility,
385:             LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots) {
386:         return newPojoHasNewOrRemovedFields(fieldSerializerSnapshots)
387:                 || fieldSerializerCompatibility.isCompatibleAfterMigration()
388:                 || preExistingRegistrationsCompatibility.isCompatibleAfterMigration();
389:     }
