423:     /**
424:      * Checks whether the new {@link PojoSerializerSnapshot} has a different subclass registration
425:      * order compared to the previous one.
426:      */
427:     private boolean newPojoHasDifferentSubclassRegistrationOrder(
428:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
429:                     registeredSubclassSerializerSnapshots) {
430:         Set<Class<?>> previousRegistrationOrder =
431:                 registeredSubclassSerializerSnapshots.unwrapOptionals().keySet();
432:         Set<Class<?>> newRegistrationOrder =
433:                 snapshotData.getRegisteredSubclassSerializerSnapshots().unwrapOptionals().keySet();
434:         return !isPreviousRegistrationPrefixOfNewRegistration(
435:                 previousRegistrationOrder, newRegistrationOrder);
436:     }
