458:     private static boolean previousSerializerHasNonRegisteredSubclasses(
459:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
460:                     nonRegisteredSubclassSerializerSnapshots) {
461:         return nonRegisteredSubclassSerializerSnapshots.size() > 0;
