144:     public TypeSerializer<T> restoreSerializer() {
145:         final int numFields = snapshotData.getFieldSerializerSnapshots().size();
146: 
147:         final ArrayList<Field> restoredFields = new ArrayList<>(numFields);
148:         final ArrayList<TypeSerializer<?>> restoredFieldSerializers = new ArrayList<>(numFields);
149:         snapshotData
