161:         final LinkedHashMap<Class<?>, TypeSerializer<?>> registeredSubclassSerializers =
162:                 restoreSerializers(
163:                         snapshotData.getRegisteredSubclassSerializerSnapshots().unwrapOptionals());
164:         final Tuple2<LinkedHashMap<Class<?>, Integer>, TypeSerializer<Object>[]>
165:                 decomposedSubclassSerializerRegistry =
166:                         decomposeSubclassSerializerRegistry(registeredSubclassSerializers);
167: 
168:         final LinkedHashMap<Class<?>, TypeSerializer<?>> nonRegisteredSubclassSerializers =
169:                 restoreSerializers(
