184:     @Override
185:     public TypeSerializerSchemaCompatibility<T> resolveSchemaCompatibility(
186:             TypeSerializerSnapshot<T> oldSerializerSnapshot) {
187:         if (!(oldSerializerSnapshot instanceof PojoSerializerSnapshot)) {
188:             return TypeSerializerSchemaCompatibility.incompatible();
189:         }
190: 
191:         PojoSerializerSnapshot<T> previousPojoSerializerSnapshot =
192:                 (PojoSerializerSnapshot<T>) oldSerializerSnapshot;
193: 
194:         final Class<T> previousPojoClass =
195:                 previousPojoSerializerSnapshot.snapshotData.getPojoClass();
196:         final LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots =
197:                 previousPojoSerializerSnapshot.snapshotData.getFieldSerializerSnapshots();
198:         final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
199:                 registeredSubclassSerializerSnapshots =
200:                         previousPojoSerializerSnapshot.snapshotData
201:                                 .getRegisteredSubclassSerializerSnapshots();
202:         final LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
203:                 nonRegisteredSubclassSerializerSnapshots =
204:                         previousPojoSerializerSnapshot.snapshotData
205:                                 .getNonRegisteredSubclassSerializerSnapshots();
206: 
207:         if (previousPojoClass != snapshotData.getPojoClass()) {
208:             return TypeSerializerSchemaCompatibility.incompatible();
209:         }
210: 
211:         if (registeredSubclassSerializerSnapshots.hasAbsentKeysOrValues()) {
212:             return TypeSerializerSchemaCompatibility.incompatible();
213:         }
214: 
215:         if (nonRegisteredSubclassSerializerSnapshots.hasAbsentKeysOrValues()) {
216:             return TypeSerializerSchemaCompatibility.incompatible();
217:         }
218: 
219:         final IntermediateCompatibilityResult<T> preExistingFieldSerializersCompatibility =
220:                 getCompatibilityOfPreExistingFields(fieldSerializerSnapshots);
221: 
222:         if (preExistingFieldSerializersCompatibility.isIncompatible()) {
223:             return TypeSerializerSchemaCompatibility.incompatible();
224:         }
225: 
226:         final IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility =
227:                 getCompatibilityOfPreExistingRegisteredSubclasses(
228:                         registeredSubclassSerializerSnapshots);
229: 
230:         if (preExistingRegistrationsCompatibility.isIncompatible()) {
231:             return TypeSerializerSchemaCompatibility.incompatible();
232:         }
233: 
234:         if (newPojoSerializerIsCompatibleAfterMigration(
235:                 preExistingFieldSerializersCompatibility,
236:                 preExistingRegistrationsCompatibility,
237:                 fieldSerializerSnapshots)) {
238: 
239:             return TypeSerializerSchemaCompatibility.compatibleAfterMigration();
240:         }
241: 
242:         if (newPojoSerializerIsCompatibleWithReconfiguredSerializer(
243:                 preExistingFieldSerializersCompatibility,
244:                 preExistingRegistrationsCompatibility,
245:                 registeredSubclassSerializerSnapshots,
246:                 nonRegisteredSubclassSerializerSnapshots)) {
247: 
248:             return TypeSerializerSchemaCompatibility.compatibleWithReconfiguredSerializer(
249:                     constructReconfiguredPojoSerializer(
250:                             preExistingFieldSerializersCompatibility,
251:                             registeredSubclassSerializerSnapshots,
252:                             preExistingRegistrationsCompatibility,
253:                             nonRegisteredSubclassSerializerSnapshots));
254:         }
255: 
256:         return TypeSerializerSchemaCompatibility.compatibleAsIs();
257:     }
