263:     /**
264:      * Transforms a {@link LinkedHashMap} with {@link TypeSerializerSnapshot}s as the value to
265:      * {@link TypeSerializer} as the value by restoring the snapshot.
266:      */
267:     private static <K> LinkedHashMap<K, TypeSerializer<?>> restoreSerializers(
268:             LinkedHashMap<K, TypeSerializerSnapshot<?>> snapshotsMap) {
269:         final LinkedHashMap<K, TypeSerializer<?>> restoredSerializersMap =
270:                 CollectionUtil.newLinkedHashMapWithExpectedSize(snapshotsMap.size());
271:         snapshotsMap.forEach(
272:                 (key, snapshot) -> restoredSerializersMap.put(key, snapshot.restoreSerializer()));
273:         return restoredSerializersMap;
274:     }
