381:     /** Checks if the new {@link PojoSerializerSnapshot} is compatible after migration. */
382:     private boolean newPojoSerializerIsCompatibleAfterMigration(
383:             IntermediateCompatibilityResult<T> fieldSerializerCompatibility,
384:             IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility,
385:             LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots) {
386:         return newPojoHasNewOrRemovedFields(fieldSerializerSnapshots)
387:                 || fieldSerializerCompatibility.isCompatibleAfterMigration()
388:                 || preExistingRegistrationsCompatibility.isCompatibleAfterMigration();
389:     }
390: 
391:     /**
392:      * Checks if the new {@link PojoSerializerSnapshot} is compatible with a reconfigured instance.
393:      */
394:     private boolean newPojoSerializerIsCompatibleWithReconfiguredSerializer(
395:             IntermediateCompatibilityResult<T> fieldSerializerCompatibility,
396:             IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility,
397:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
398:                     registeredSubclassSerializerSnapshots,
399:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
400:                     nonRegisteredSubclassSerializerSnapshots) {
401:         return newPojoHasDifferentSubclassRegistrationOrder(registeredSubclassSerializerSnapshots)
402:                 || previousSerializerHasNonRegisteredSubclasses(
403:                         nonRegisteredSubclassSerializerSnapshots)
404:                 || fieldSerializerCompatibility.isCompatibleWithReconfiguredSerializer()
405:                 || preExistingRegistrationsCompatibility.isCompatibleWithReconfiguredSerializer();
406:     }
