408:     /**
409:      * Checks whether the new {@link PojoSerializerSnapshot} has new or removed fields compared to
410:      * the previous one.
411:      */
412:     private boolean newPojoHasNewOrRemovedFields(
413:             LinkedOptionalMap<Field, TypeSerializerSnapshot<?>> fieldSerializerSnapshots) {
414:         int numRemovedFields = fieldSerializerSnapshots.absentKeysOrValues().size();
415:         int numPreexistingFields = fieldSerializerSnapshots.size() - numRemovedFields;
416: 
417:         boolean hasRemovedFields = numRemovedFields > 0;
418:         boolean hasNewFields =
419:                 snapshotData.getFieldSerializerSnapshots().size() - numPreexistingFields > 0;
420:         return hasRemovedFields || hasNewFields;
421:     }
422: 
423:     /**
424:      * Checks whether the new {@link PojoSerializerSnapshot} has a different subclass registration
425:      * order compared to the previous one.
426:      */
427:     private boolean newPojoHasDifferentSubclassRegistrationOrder(
428:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
429:                     registeredSubclassSerializerSnapshots) {
430:         Set<Class<?>> previousRegistrationOrder =
431:                 registeredSubclassSerializerSnapshots.unwrapOptionals().keySet();
432:         Set<Class<?>> newRegistrationOrder =
433:                 snapshotData.getRegisteredSubclassSerializerSnapshots().unwrapOptionals().keySet();
434:         return !isPreviousRegistrationPrefixOfNewRegistration(
435:                 previousRegistrationOrder, newRegistrationOrder);
436:     }
437: 
438:     private static boolean isPreviousRegistrationPrefixOfNewRegistration(
439:             Set<Class<?>> previousRegistrationOrder, Set<Class<?>> newRegistrationOrder) {
440:         Iterator<Class<?>> newRegistrationItr = newRegistrationOrder.iterator();
441: 
442:         for (Class<?> previousRegisteredClass : previousRegistrationOrder) {
443:             if (!newRegistrationItr.hasNext()) {
444:                 return false;
445:             }
446:             Class<?> newRegisteredClass = newRegistrationItr.next();
447:             if (!previousRegisteredClass.equals(newRegisteredClass)) {
448:                 return false;
449:             }
450:         }
451:         return true;
452:     }
453: 
454:     /**
455:      * Checks whether the previous serializer, represented by this snapshot, has non-registered
456:      * subclasses.
457:      */
458:     private static boolean previousSerializerHasNonRegisteredSubclasses(
459:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
460:                     nonRegisteredSubclassSerializerSnapshots) {
461:         return nonRegisteredSubclassSerializerSnapshots.size() > 0;
462:     }
