464:     /**
465:      * Creates a reconfigured version of the {@link PojoSerializerSnapshot}.
466:      *
467:      * @param fieldSerializerCompatibility compatibility of preexisting fields' serializers.
468:      * @param registeredSerializerSnapshots snapshot of previous registered subclasses' serializers.
469:      * @param preExistingRegistrationsCompatibility compatibility of preexisting subclasses'
470:      *     serializers.
471:      * @param nonRegisteredSubclassSerializerSnapshots snapshot of previous non-registered
472:      *     subclasses' serializers.
473:      * @return a reconfigured version of the original new {@link PojoSerializer}.
474:      */
475:     private PojoSerializer<T> constructReconfiguredPojoSerializer(
476:             IntermediateCompatibilityResult<T> fieldSerializerCompatibility,
477:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>> registeredSerializerSnapshots,
478:             IntermediateCompatibilityResult<T> preExistingRegistrationsCompatibility,
479:             LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
480:                     nonRegisteredSubclassSerializerSnapshots) {
481: 
482:         @SuppressWarnings("unchecked")
483:         final TypeSerializer<Object>[] reconfiguredFieldSerializers =
484:                 constructReconfiguredFieldSerializers(fieldSerializerCompatibility);
485: 
486:         Tuple2<LinkedHashMap<Class<?>, Integer>, TypeSerializer<Object>[]>
487:                 reconfiguredSubclassRegistry =
488:                         constructReconfiguredSubclassRegistrations(
489:                                 snapshotData
490:                                         .getRegisteredSubclassSerializerSnapshots()
491:                                         .unwrapOptionals(),
492:                                 registeredSerializerSnapshots,
493:                                 preExistingRegistrationsCompatibility);
494: 
495:         return new PojoSerializer<>(
496:                 snapshotData.getPojoClass(),
497:                 snapshotData
498:                         .getFieldSerializerSnapshots()
499:                         .unwrapOptionals()
500:                         .keySet()
501:                         .toArray(new Field[0]),
502:                 reconfiguredFieldSerializers,
503:                 reconfiguredSubclassRegistry.f0,
504:                 reconfiguredSubclassRegistry.f1,
505:                 restoreSerializers(nonRegisteredSubclassSerializerSnapshots.unwrapOptionals()),
506:                 executionConfig);
507:     }
508: 
509:     private static TypeSerializer[] constructReconfiguredFieldSerializers(
510:             IntermediateCompatibilityResult<?> fieldSerializerCompatibility) {
511:         checkArgument(
512:                 !fieldSerializerCompatibility.isIncompatible()
513:                         && !fieldSerializerCompatibility.isCompatibleAfterMigration());
514:         return fieldSerializerCompatibility.getNestedSerializers();
515:     }
516: 
517:     private static Tuple2<LinkedHashMap<Class<?>, Integer>, TypeSerializer<Object>[]>
518:             constructReconfiguredSubclassRegistrations(
519:                     LinkedHashMap<Class<?>, TypeSerializerSnapshot<?>> newSubclassRegistrations,
520:                     LinkedOptionalMap<Class<?>, TypeSerializerSnapshot<?>>
521:                             oldRegisteredSerializerSnapshots,
522:                     IntermediateCompatibilityResult<?> preExistingRegistrationsCompatibility) {
523: 
524:         checkArgument(
525:                 !preExistingRegistrationsCompatibility.isIncompatible()
526:                         && !preExistingRegistrationsCompatibility.isCompatibleAfterMigration());
527: 
528:         LinkedHashMap<Class<?>, TypeSerializer<?>> reconfiguredSubclassSerializerRegistry =
529:                 restoreSerializers(oldRegisteredSerializerSnapshots.unwrapOptionals());
530: 
531:         Iterator<TypeSerializer<?>> serializersForPreexistingRegistrations =
532:                 Arrays.asList(preExistingRegistrationsCompatibility.getNestedSerializers())
533:                         .iterator();
534: 
535:         // first, replace all restored serializers of subclasses that co-exist in
536:         // the previous and new registrations, with the compatibility-checked serializers
537:         for (Map.Entry<Class<?>, TypeSerializer<?>> oldRegistration :
538:                 reconfiguredSubclassSerializerRegistry.entrySet()) {
539:             if (newSubclassRegistrations.containsKey(oldRegistration.getKey())) {
540:                 oldRegistration.setValue(serializersForPreexistingRegistrations.next());
541:             }
542:         }
543: 
544:         // then, for all new registration that did not exist before, append it to the registry
545:         // simply with their
546:         // new serializers
547:         for (Map.Entry<Class<?>, TypeSerializerSnapshot<?>> newRegistration :
548:                 newSubclassRegistrations.entrySet()) {
549:             TypeSerializer<?> oldRegistration =
550:                     reconfiguredSubclassSerializerRegistry.get(newRegistration.getKey());
551:             if (oldRegistration == null) {
552:                 reconfiguredSubclassSerializerRegistry.put(
553:                         newRegistration.getKey(), newRegistration.getValue().restoreSerializer());
554:             }
555:         }
556: 
557:         return decomposeSubclassSerializerRegistry(reconfiguredSubclassSerializerRegistry);
558:     }
