166:     @Override
167:     public PojoSerializer<T> duplicate() {
168:         TypeSerializer<Object>[] duplicateFieldSerializers = duplicateSerializers(fieldSerializers);
169:         TypeSerializer<Object>[] duplicateRegisteredSerializers =
170:                 duplicateSerializers(registeredSerializers);
171: 
172:         return new PojoSerializer<>(
173:                 clazz,
174:                 fields,
175:                 duplicateFieldSerializers,
176:                 new LinkedHashMap<>(registeredClasses),
177:                 duplicateRegisteredSerializers,
178:                 subclassSerializerCache.entrySet().stream()
179:                         .collect(
180:                                 Collectors.toMap(Map.Entry::getKey, e -> e.getValue().duplicate())),
181:                 executionConfig);
182:     }
183: 
184:     @SuppressWarnings("unchecked")
185:     private TypeSerializer<Object>[] duplicateSerializers(TypeSerializer<?>[] serializers) {
186:         boolean stateful = false;
187:         TypeSerializer<?>[] duplicateSerializers = new TypeSerializer[serializers.length];
188: 
189:         for (int i = 0; i < serializers.length; i++) {
190:             duplicateSerializers[i] = serializers[i].duplicate();
191:             if (duplicateSerializers[i] != serializers[i]) {
192:                 // at least one of them is stateful
193:                 stateful = true;
194:             }
195:         }
196: 
197:         if (!stateful) {
198:             // as a small memory optimization, we can share the same object between instances
199:             duplicateSerializers = serializers;
200:         }
201:         return (TypeSerializer<Object>[]) duplicateSerializers;
202:     }
203: 
204:     @Override
205:     public T createInstance() {
206:         if (clazz.isInterface() || Modifier.isAbstract(clazz.getModifiers()) || isRecord()) {
207:             return null;
208:         }
209:         try {
210:             T t = clazz.newInstance();
211:             initializeFields(t);
212:             return t;
213:         } catch (Exception e) {
214:             throw new RuntimeException("Cannot instantiate class.", e);
215:         }
216:     }
217: 
218:     protected void initializeFields(T t) {
219:         for (int i = 0; i < numFields; i++) {
220:             if (fields[i] != null) {
221:                 try {
222:                     fields[i].set(t, fieldSerializers[i].createInstance());
223:                 } catch (IllegalAccessException e) {
224:                     throw new RuntimeException("Cannot initialize fields.", e);
225:                 }
226:             }
227:         }
228:     }
