230:     @Override
231:     @SuppressWarnings({"unchecked", "rawtypes"})
232:     public T copy(T from) {
233:         if (from == null) {
234:             return null;
235:         }
236: 
237:         Class<?> actualType = from.getClass();
238:         if (isRecord()) {
239:             try {
240:                 JavaRecordBuilderFactory<T>.JavaRecordBuilder builder = recordFactory.newBuilder();
241:                 for (int i = 0; i < numFields; i++) {
242:                     if (fields[i] != null) {
243:                         builder.setField(i, copyField(i, from));
244:                     }
245:                 }
246:                 return builder.build();
247:             } catch (IllegalAccessException e) {
248:                 throw new RuntimeException(
249:                         "Error during POJO copy, this should not happen since we check the fields before.");
250:             }
251:         } else if (actualType == clazz) {
252:             T target;
253:             try {
254:                 target = (T) from.getClass().newInstance();
255:             } catch (Throwable t) {
256:                 throw new RuntimeException("Cannot instantiate class.", t);
257:             }
258:             // no subclass
259:             try {
260:                 for (int i = 0; i < numFields; i++) {
261:                     if (fields[i] != null) {
262:                         fields[i].set(target, copyField(i, from));
263:                     }
264:                 }
265:             } catch (IllegalAccessException e) {
266:                 throw new RuntimeException(
267:                         "Error during POJO copy, this should not happen since we check the fields before.");
268:             }
269:             return target;
270:         } else {
271:             // subclass
272:             TypeSerializer subclassSerializer = getSubclassSerializer(actualType);
273:             return (T) subclassSerializer.copy(from);
274:         }
275:     }
276: 
277:     @Override
278:     @SuppressWarnings({"unchecked", "rawtypes"})
279:     public T copy(T from, T reuse) {
280:         if (from == null) {
281:             return null;
282:         }
283: 
284:         Class<?> actualType = from.getClass();
285:         if (reuse == null || actualType != reuse.getClass()) {
286:             // cannot reuse, do a non-reuse copy
287:             return copy(from);
288:         }
289: 
290:         if (isRecord()) {
291:             try {
292:                 JavaRecordBuilderFactory<T>.JavaRecordBuilder builder = recordFactory.newBuilder();
293:                 for (int i = 0; i < numFields; i++) {
294:                     if (fields[i] != null) {
295:                         builder.setField(i, copyField(reuse, i, from));
296:                     }
297:                 }
298:                 return builder.build();
299:             } catch (IllegalAccessException e) {
300:                 throw new RuntimeException(
301:                         "Error during POJO copy, this should not happen since we check the fields before.");
302:             }
303:         } else if (actualType == clazz) {
304:             try {
305:                 for (int i = 0; i < numFields; i++) {
306:                     if (fields[i] != null) {
307:                         fields[i].set(reuse, copyField(reuse, i, from));
308:                     }
309:                 }
310:             } catch (IllegalAccessException e) {
311:                 throw new RuntimeException(
312:                         "Error during POJO copy, this should not happen since we check the fields before.",
313:                         e);
314:             }
315:         } else {
316:             TypeSerializer subclassSerializer = getSubclassSerializer(actualType);
317:             reuse = (T) subclassSerializer.copy(from, reuse);
318:         }
319: 
320:         return reuse;
321:     }
322: 
323:     private Object copyField(int i, Object from) throws IllegalAccessException {
324:         Object value = fields[i].get(from);
325:         if (value != null) {
326:             return fieldSerializers[i].copy(value);
327:         } else {
328:             return null;
329:         }
330:     }
331: 
332:     private Object copyField(T reuse, int i, Object from) throws IllegalAccessException {
333:         Object value = fields[i].get(from);
334:         if (value != null) {
335:             Object reuseValue = fields[i].get(reuse);
336: 
337:             if (reuseValue != null) {
338:                 return fieldSerializers[i].copy(value, reuseValue);
339:             } else {
340:                 return fieldSerializers[i].copy(value);
341:             }
342:         } else {
343:             return null;
344:         }
345:     }
