352:     @Override
353:     @SuppressWarnings({"unchecked", "rawtypes"})
354:     public void serialize(T value, DataOutputView target) throws IOException {
355:         int flags = 0;
356:         // handle null values
357:         if (value == null) {
358:             flags |= IS_NULL;
359:             target.writeByte(flags);
360:             return;
361:         }
362: 
363:         Integer subclassTag = -1;
364:         Class<?> actualClass = value.getClass();
365:         TypeSerializer subclassSerializer = null;
366:         if (clazz != actualClass) {
367:             subclassTag = registeredClasses.get(actualClass);
368:             if (subclassTag != null) {
369:                 flags |= IS_TAGGED_SUBCLASS;
370:                 subclassSerializer = registeredSerializers[subclassTag];
371:             } else {
372:                 flags |= IS_SUBCLASS;
373:                 subclassSerializer = getSubclassSerializer(actualClass);
374:             }
375:         } else {
376:             flags |= NO_SUBCLASS;
377:         }
378: 
379:         target.writeByte(flags);
380: 
381:         // if its a registered subclass, write the class tag id, otherwise write the full classname
382:         if ((flags & IS_SUBCLASS) != 0) {
383:             target.writeUTF(actualClass.getName());
384:         } else if ((flags & IS_TAGGED_SUBCLASS) != 0) {
385:             target.writeByte(subclassTag);
386:         }
387: 
388:         // if its a subclass, use the corresponding subclass serializer,
389:         // otherwise serialize each field with our field serializers
390:         if ((flags & NO_SUBCLASS) != 0) {
391:             try {
392:                 for (int i = 0; i < numFields; i++) {
393:                     Object o = (fields[i] != null) ? fields[i].get(value) : null;
394:                     if (o == null) {
395:                         target.writeBoolean(true); // null field handling
396:                     } else {
397:                         target.writeBoolean(false);
398:                         fieldSerializers[i].serialize(o, target);
399:                     }
400:                 }
401:             } catch (IllegalAccessException e) {
402:                 throw new RuntimeException(
403:                         "Error during POJO copy, this should not happen since we check the fields before.",
404:                         e);
405:             }
406:         } else {
407:             // subclass
408:             if (subclassSerializer != null) {
409:                 subclassSerializer.serialize(value, target);
410:             }
411:         }
412:     }
